# frozen_string_literal: true

require_relative "test_helper"

# Operations added for full Backend API coverage, table-driven: each row names the
# operation (verb and path with {} for every parameter), calls one SDK method and
# asserts the HTTP verb, the exact URL (the first path parameter is "a/b" to prove
# path encoding; the first query parameter is sent as 5), the JSON body and the
# Idempotency-Key header. test/parity_operations.txt lists the operations the table
# must cover, so a new row without a listed operation, or a listed operation
# without a row, fails.
