  def test_every_listed_operation_has_a_row
    listed = File.readlines(File.join(__dir__, "parity_operations.txt"), chomp: true).reject(&:empty?)
    keys = OPERATIONS.map(&:first)
    assert_equal listed.sort, keys.sort
    assert_equal keys.uniq.length, keys.length
  end

  def test_every_operation_hits_its_route
    OPERATIONS.each do |key, verb, path, body, idem, call|
      http = Atlas::Test::StubRequester.new
      client = Atlas::Client.new("sk_test_123", http: http)
      http.enqueue(body: { "ok" => true })
      call.call(client)

      req = http.last
      assert_equal verb, req.method, key
      assert_equal "https://api.atlasauth.net#{path}", req.url, key
      if body.nil?
        assert_nil req.body, "#{key} should send no body"
      else
        assert_equal body, JSON.parse(req.body), "#{key} body"
        assert_equal "application/json", req.headers["content-type"]
      end
      if idem
        assert_equal "idem_1", req.headers["idempotency-key"], "#{key} idempotency"
      else
        refute req.headers.key?("idempotency-key"), key
      end
    end
  end
end
